export const contractSchemaTexts: Readonly<Record<string, string>> = {
  "authoring-import.v1": "{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"authoring-import.v1.json\",\"title\":\"Feature tree import document v1\",\"description\":\"The import/export table of 13.1.1-T5 (route 25, AC13/AC14/AC15): one flat row set that carries the whole feature tree — nodes, their checklist items and each item's manual test cases — in a single document. The same table is what the CSV and XLSX readers produce and what every exporter writes, so the three formats validate against one contract; the CSV/XLSX column order is the CSV header (kind,key,parent_key,item_key,node_kind,title,description,precondition,steps,priority,state,code,position) and a JSON member of a row is that column name. Rows are ordered parent-first: a node's parent_key names a node row above it, an item's parent_key names its node, a case's item_key names its item. 'steps' is the stored {\\\"steps\\\":[…]} document of contracts/schemas/authoring-steps.v1.json, inlined here as $defs.steps because a row member is not a reference to another contract file: the two shapes must stay identical (1..100 steps, 2000 characters per field, closed members), which ContractSchemaRegistryTests.AuthoringImportSchema_IsDiscovered asserts field by field. Bounds: 1..5000 rows — the same 5000-row cap the route enforces with 413 payload_too_large (plan 13.1.1 §5 route 25, AC16) — a node title of 1..200 and an item/case title of 1..500 code points, a description and a precondition of at most 4000, and the priority/state/node_kind sets of plan 13.1.1 §4. No member is ever evaluated as a formula: the JSON format is never neutralised, because a JSON consumer does not evaluate cell text (AC16 covers CSV and XLSX only).\",\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"format\",\"version\",\"rows\"],\"properties\":{\"format\":{\"const\":\"authoring-import\",\"description\":\"The document discriminator, so a file of the wrong kind is one refusal at /format (reason unsupported_format) rather than a hundred per-row ones.\"},\"version\":{\"const\":1,\"description\":\"The document version; a later format is a new file (authoring-import.v2.json), never a reinterpretation of this one.\"},\"rows\":{\"type\":\"array\",\"minItems\":1,\"maxItems\":5000,\"description\":\"The data rows, in file order. At least one: an import of nothing is a mistake, and the route answers 422 with value_invalid at /rows. At most 5000: the route refuses a longer file with 413 payload_too_large before this schema runs, and the reader counts rows before materialising them.\",\"items\":{\"type\":\"object\",\"required\":[\"kind\"],\"properties\":{\"kind\":{\"enum\":[\"node\",\"item\",\"case\"],\"description\":\"The row's kind, and the member every if/then branch below selects on. A row with any other value is refused here rather than by the branches, so an unknown kind is one refusal at this member.\"}},\"allOf\":[{\"if\":{\"properties\":{\"kind\":{\"const\":\"node\"}},\"required\":[\"kind\"]},\"then\":{\"$ref\":\"#/$defs/node\"}},{\"if\":{\"properties\":{\"kind\":{\"const\":\"item\"}},\"required\":[\"kind\"]},\"then\":{\"$ref\":\"#/$defs/item\"}},{\"if\":{\"properties\":{\"kind\":{\"const\":\"case\"}},\"required\":[\"kind\"]},\"then\":{\"$ref\":\"#/$defs/case\"}}]}}},\"$defs\":{\"key\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":64,\"pattern\":\"^[A-Za-z0-9][A-Za-z0-9_.:-]*$\",\"description\":\"A row's file-local key: nodes n1…, items i1…, cases c1… on export, numbered in depth-first tree order (node by position,id; its items by position,id; each item's cases by code,id), so an unchanged tree exports byte-identically. A key is only ever compared with another key of the same file, which is why it is restricted to characters that survive every format unchanged (no commas, quotes, line breaks or leading spaces) and to 64 characters.\"},\"position\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":1000000,\"description\":\"The sibling position of a NEW row only: absent means append at the group's max + 1, and a position a live sibling already holds is refused with value_invalid at /position. Import never reorders an existing sibling. The upper bound is the sanity ceiling of a hand-written file — a sibling group holds at most 1000 nodes (NodeLimits.MaximumSiblingsPerGroup), so a position above 1e6 names nothing this module could ever store.\"},\"itemPriority\":{\"enum\":[\"critical\",\"high\",\"medium\",\"low\"],\"description\":\"The priority CHECK of checklist_item and manual_test_case (plan 13.1.1 §4).\"},\"node\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"kind\",\"key\",\"node_kind\",\"title\"],\"description\":\"One feature_node row: a module at the root (no parent_key), or a feature/category/sub_category under the node named by parent_key.\",\"properties\":{\"kind\":{\"const\":\"node\"},\"key\":{\"$ref\":\"#/$defs/key\"},\"parent_key\":{\"$ref\":\"#/$defs/key\",\"description\":\"The parent node's key, or absent for a module. A key naming no node above this row is unknown_parent; a module carrying one is unknown_parent too (the depth ladder of AC1).\"},\"node_kind\":{\"enum\":[\"module\",\"feature\",\"category\",\"sub_category\"],\"description\":\"The kind ladder of AC1: module at the root, feature under module, category under feature, sub_category under category.\"},\"title\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":200,\"description\":\"The node title, 1..200 code points (plan 13.1.1 §4, the feature_node_title_check bound).\"},\"position\":{\"$ref\":\"#/$defs/position\"}}},\"item\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"kind\",\"key\",\"parent_key\",\"title\",\"priority\"],\"description\":\"One checklist_item row under the node named by parent_key (a category or a sub_category, AC3).\",\"properties\":{\"kind\":{\"const\":\"item\"},\"key\":{\"$ref\":\"#/$defs/key\"},\"parent_key\":{\"$ref\":\"#/$defs/key\",\"description\":\"The owning node's key; it must be a node row above this one and of kind category or sub_category (AC3).\"},\"title\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":500,\"description\":\"The item title, 1..500 code points (plan 13.1.1 §4, checklist_item_title_check).\"},\"description\":{\"type\":\"string\",\"maxLength\":4000,\"description\":\"Optional item description, at most 4000 code points (checklist_item_description_check).\"},\"priority\":{\"$ref\":\"#/$defs/itemPriority\"},\"state\":{\"enum\":[\"draft\",\"active\",\"retired\"],\"description\":\"Optional state of an item row. An empty or absent cell means \\\"keep the stored state\\\" for a row that already exists, and the creation default of AC3 (active) for a new one. A non-empty value must be a move the state routes themselves allow (the same state machine the authoring writes use), otherwise the row is refused at /state and nothing is written; a new row takes the file's value so an export re-imports unchanged, and an item that already exists cannot be retired by a file: a move into retired needs a reason, which a row has no column for, so it is refused at /state.\"},\"position\":{\"$ref\":\"#/$defs/position\"}}},\"case\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"kind\",\"key\",\"item_key\",\"title\",\"priority\",\"steps\"],\"description\":\"One manual_test_case row under the item named by item_key.\",\"properties\":{\"kind\":{\"const\":\"case\"},\"key\":{\"$ref\":\"#/$defs/key\"},\"item_key\":{\"$ref\":\"#/$defs/key\",\"description\":\"The owning item's key; it must be an item row above this one (a case names its item, never a node).\"},\"title\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":500,\"description\":\"The case title, 1..500 code points (plan 13.1.1 §4, manual_test_case_title_check).\"},\"description\":{\"type\":\"string\",\"maxLength\":4000,\"description\":\"Optional case description, at most 4000 code points (manual_test_case_description_check).\"},\"precondition\":{\"type\":\"string\",\"maxLength\":4000,\"description\":\"Optional case precondition, at most 4000 code points (manual_test_case_precondition_check).\"},\"steps\":{\"$ref\":\"#/$defs/steps\",\"description\":\"The steps document; required because manual_test_case.steps is NOT NULL and the writer validates every case snapshot through authoring-steps.v1 (Notes, OI-13-115).\"},\"priority\":{\"$ref\":\"#/$defs/itemPriority\"},\"state\":{\"enum\":[\"draft\",\"approved\",\"retired\"],\"description\":\"Optional state of a case row. An empty or absent cell means \\\"keep the stored state\\\" for a row that already exists, and the creation default (draft) for a new one. A non-empty value must be a move the state routes themselves allow, otherwise the row is refused at /state and nothing is written; a restore of a soft-deleted case always writes draft, whatever the file says, and a retired row stays unwritable. A move into retired needs a reason, which a row has no column for, so an import never retires an existing row (it is refused at /state); a new row takes the file's state, so an export that carries a retired case re-imports unchanged. Use the item or case state route to retire a row that already exists.\"},\"code\":{\"type\":\"string\",\"pattern\":\"^([A-Z][A-Z0-9]{1,7}-[0-9]{3,10})?$\",\"description\":\"The case code, which is how a re-import finds its row (AC15): present must carry the project's own case_prefix (the manual_test_case code CHECK), absent or empty means 'allocate a fresh number'. A code that matches a live case updates it, one that matches a soft-deleted case restores it, and one whose prefix is not this project's prefix is code_conflict.\"},\"position\":{\"$ref\":\"#/$defs/position\"}}},\"steps\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"steps\"],\"description\":\"The manual test case steps document of contracts/schemas/authoring-steps.v1.json, inlined (a cross-file $ref would tie this contract to the steps file's own $id, and the two documents are validated by the same registry anyway). The bounds here are that file's bounds: a change to one must change the other, which ContractSchemaRegistryTests.AuthoringImportSchema_IsDiscovered checks member by member.\",\"properties\":{\"steps\":{\"type\":\"array\",\"minItems\":1,\"maxItems\":100,\"description\":\"The steps in the order the tester performs them; the array order is the step order, 'no' is the number shown to the tester.\",\"items\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"no\",\"action\",\"expected\"],\"properties\":{\"no\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":1000,\"description\":\"The step number shown to the tester (1..1000, the same inference as authoring-steps.v1).\"},\"action\":{\"type\":\"string\",\"maxLength\":2000,\"description\":\"What the tester does, at most 2000 characters.\"},\"expected\":{\"type\":\"string\",\"maxLength\":2000,\"description\":\"What the tester must observe, at most 2000 characters.\"},\"data\":{\"type\":\"string\",\"maxLength\":2000,\"description\":\"Test data used by the step, optional and always text, at most 2000 characters.\"}}}}}}}}",
  "authoring-steps.v1": "{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"authoring-steps.v1.json\",\"title\":\"Manual test case steps v1\",\"description\":\"The steps document of one manual test case (13.1.1-T1.2, routes 13 and 15): an object carrying 1..100 steps, each with a number, an action, an expected result and optional data. Unknown members are refused at the document level and inside a step, so a typo is a 422 rather than silently stored content. The document is stored as the manual_test_case.steps jsonb value, whose CHECK is jsonb_typeof(steps) = 'object' (plan 13.1.1 §4), which is why the root is an object and the step array sits under 'steps'. Bounds: 1..100 steps and 2000 characters per field are plan 13.1.1 §3 (the schema file's own row); the 'no' range is [INFERENCE] — the plan names the member without a bound, so it is pinned to the same 1..1000 window a renumbered import can produce. No minLength: the plan states only the upper bound, so empty text is the command layer's semantic check, not this schema's. Text is NFC-normalised (Evidgate.Modules.Authoring.Domain.AuthoringText) before validation, never by the schema, and JSON Schema maxLength counts code points — the same unit as PostgreSQL char_length. No x-max-bytes: the 64 KiB cap is the case route's body cap (plan 13.1.1 §8), and the document is carried inside that body.\",\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"steps\"],\"properties\":{\"steps\":{\"type\":\"array\",\"minItems\":1,\"maxItems\":100,\"description\":\"The steps in the order the tester performs them; the array order is the step order, 'no' is the number shown to the tester.\",\"items\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"no\",\"action\",\"expected\"],\"properties\":{\"no\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":1000,\"description\":\"[INFERENCE] The step number shown to the tester; the plan names the member without a bound, pinned here to 1..1000 so an import that keeps its own numbering stays valid. Array order, not this value, is the order of execution.\"},\"action\":{\"type\":\"string\",\"maxLength\":2000,\"description\":\"What the tester does (plan 13 §4.1 'action', at most 2000 characters — plan 13.1.1 §3).\"},\"expected\":{\"type\":\"string\",\"maxLength\":2000,\"description\":\"What the tester must observe (plan 13 §4.1 'expected', at most 2000 characters — plan 13.1.1 §3).\"},\"data\":{\"type\":\"string\",\"maxLength\":2000,\"description\":\"Test data used by the step (plan 13 §4.1 'data'), optional and always text — never a nested object — at most 2000 characters (plan 13.1.1 §3).\"}}}}}}",
  "capability.v1": "{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"capability.v1.json\",\"title\":\"Adapter capability document v1\",\"description\":\"00 §10 adapter protocol capability document (04.7.1-T1.1). The server rejects an incompatible protocol.major; supports is extensible — flags the server does not know are recorded verbatim in adapter_capability.supports and never evaluated (04.7.1 AC3). capture_control: false declares that the adapter cannot honour the run-create configuration document (contracts/adapter/config.v1.json), so its runs carry the capture_uncontrolled label (T97, AC7); an absent capture_control means the configuration document must be honoured. The document is untrusted input capped at 16 KiB. See contracts/README.md for the *.vN.json versioning rule.\",\"x-max-bytes\":16384,\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"protocol\",\"engine\",\"platforms\",\"supports\",\"mode\"],\"properties\":{\"protocol\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"major\",\"minor\"],\"properties\":{\"major\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":2147483647},\"minor\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":2147483647}}},\"engine\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"family\",\"version\"],\"properties\":{\"family\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":64},\"version\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":128,\"description\":\"Exact engine version; carried here and (V2) pinned in the immutable JobSpec with the image digest — runners never resolve 'latest' at run time (D8)\"}}},\"platforms\":{\"type\":\"array\",\"minItems\":1,\"maxItems\":16,\"uniqueItems\":true,\"items\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":64}},\"supports\":{\"type\":\"object\",\"maxProperties\":32,\"required\":[\"discovery\",\"step_events\",\"retry\",\"cancel\"],\"properties\":{\"discovery\":{\"type\":\"boolean\"},\"step_events\":{\"type\":\"boolean\"},\"retry\":{\"type\":\"boolean\"},\"cancel\":{\"type\":\"boolean\"},\"capture_control\":{\"type\":\"boolean\",\"description\":\"false = the adapter cannot honour contracts/adapter/config.v1.json at run create, so the run carries the capture_uncontrolled label (T97, AC7); absent = the configuration document is delivered and must be honoured\"}},\"additionalProperties\":{\"type\":\"boolean\",\"description\":\"A support flag this server does not know: ignored, never evaluated, and stored verbatim (04.7.1 AC3)\"}},\"mode\":{\"type\":\"string\",\"enum\":[\"full\",\"ingest_only\"],\"description\":\"ingest_only results are viewable but not gate-eligible unless the manifest is proven complete (00 §10)\"}}}",
  "cleanup.v1": "{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"cleanup.v1.json\",\"title\":\"Adapter operation: cleanup v1\",\"description\":\"00 §10 protocol operation 'cleanup' (04.7.1-T1.2). Direction: adapter → server — the adapter reports the run namespace it cleaned, the resources it removed and, separately, the ones it could not (source §4: 'idempotent resource cleanup; reports separately if cleanup fails'). A cleanup failure is reported in failed[] and/or as error.code, never as a silent success. At least one of `cleanup` and `error` is required, so a phase that produces nothing still reports why (contracts/adapter/README.md).\",\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"protocol\",\"operation\"],\"anyOf\":[{\"required\":[\"cleanup\"]},{\"required\":[\"error\"]}],\"properties\":{\"protocol\":{\"$ref\":\"#/$defs/protocol\"},\"operation\":{\"const\":\"cleanup\"},\"run_id\":{\"type\":\"string\",\"format\":\"uuid\"},\"cleanup\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"namespace\"],\"properties\":{\"namespace\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":128},\"removed\":{\"type\":\"array\",\"maxItems\":256,\"uniqueItems\":true,\"items\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":256}},\"failed\":{\"type\":\"array\",\"maxItems\":256,\"uniqueItems\":true,\"items\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":256}}}},\"error\":{\"$ref\":\"#/$defs/operationError\"}},\"$defs\":{\"protocol\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"major\",\"minor\"],\"properties\":{\"major\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":2147483647},\"minor\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":2147483647}}},\"operationError\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"code\"],\"properties\":{\"code\":{\"type\":\"string\",\"pattern\":\"^[a-z][a-z0-9_]{0,63}$\"},\"message\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":512}}}}}",
  "collect.v1": "{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"collect.v1.json\",\"title\":\"Adapter operation: collect v1\",\"description\":\"00 §10 protocol operation 'collect' (04.7.1-T1.2). Direction: adapter → server — the artifact inventory collected from the allowed workspace directory, reported as the shared 00 §9.4 event envelope whose artifact_ids carry the collected artifacts (source §4: 'artifact inventory, checksum; never reads files outside the workspace'). The envelope schema is referenced by $id (urn:evidgate:contract:event-envelope.v1), never copied. At most 500 events, like the ingest batch (00 §9.3). A failed phase reports `error` instead of the payload: at least one of `events` and `error` is required (contracts/adapter/README.md).\",\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"protocol\",\"operation\"],\"anyOf\":[{\"required\":[\"events\"]},{\"required\":[\"error\"]}],\"properties\":{\"protocol\":{\"$ref\":\"#/$defs/protocol\"},\"operation\":{\"const\":\"collect\"},\"run_id\":{\"type\":\"string\",\"format\":\"uuid\"},\"events\":{\"type\":\"array\",\"minItems\":1,\"maxItems\":500,\"items\":{\"$ref\":\"urn:evidgate:contract:event-envelope.v1#/$defs/event\"}},\"error\":{\"$ref\":\"#/$defs/operationError\"}},\"$defs\":{\"protocol\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"major\",\"minor\"],\"properties\":{\"major\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":2147483647},\"minor\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":2147483647}}},\"operationError\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"code\"],\"properties\":{\"code\":{\"type\":\"string\",\"pattern\":\"^[a-z][a-z0-9_]{0,63}$\"},\"message\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":512}}}}}",
  "config.v1": "{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"config.v1.json\",\"title\":\"Adapter run configuration document v1\",\"description\":\"The adapter protocol v1 run-create configuration document (T97, 04.7.1-T1.2). It is assembled server-side at run create (05.2.1-T1 from 06.2.2's per-project capture flags, redaction patterns and per-kind size caps) and delivered to the adapter, which applies redaction and skips capture for a disabled kind before any byte leaves the CI runner. A capability document declaring capture_control: false may ignore this document; the run is then labelled capture_uncontrolled (04.7.1 AC7). Directions: server → adapter. Kinds are the closed 00 §7 artifact-kind list; redaction rule types are the 06.2.2 allowlist. The body is capped at 64 KiB (x-max-bytes) as a defensive transport bound — the 04.7.1 §8 16 KiB rule applies to the capability document, which the adapter sends.\",\"x-max-bytes\":65536,\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"schema_version\",\"run_id\",\"kinds\"],\"properties\":{\"schema_version\":{\"const\":1},\"run_id\":{\"type\":\"string\",\"format\":\"uuid\"},\"project_id\":{\"type\":\"string\",\"format\":\"uuid\"},\"kinds\":{\"type\":\"object\",\"additionalProperties\":false,\"description\":\"The closed 00 §7 artifact-kind list; a kind outside it is an unknown member and is rejected here as well as by 06.1.2's kind lookup\",\"properties\":{\"trace\":{\"$ref\":\"#/$defs/kindPolicy\"},\"video\":{\"$ref\":\"#/$defs/kindPolicy\"},\"screenshot\":{\"$ref\":\"#/$defs/kindPolicy\"},\"raw_report\":{\"$ref\":\"#/$defs/kindPolicy\"},\"dom_snapshot\":{\"$ref\":\"#/$defs/kindPolicy\"},\"a11y_snapshot\":{\"$ref\":\"#/$defs/kindPolicy\"},\"patch\":{\"$ref\":\"#/$defs/kindPolicy\"},\"ui_hierarchy\":{\"$ref\":\"#/$defs/kindPolicy\"}}}},\"$defs\":{\"kindPolicy\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"capture_enabled\"],\"properties\":{\"capture_enabled\":{\"type\":\"boolean\",\"description\":\"false = the adapter must not capture this kind at all (06.2.2 AC4); the server never receives pre-redaction bytes\"},\"max_bytes\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":1099511627776,\"description\":\"Per-kind policy cap (06 artifact_kind_policy.max_bytes); 1 TiB is the schema's sanity bound, the real default is 06.1.2-T3.1's per-kind value\"},\"redaction_rules\":{\"type\":\"array\",\"maxItems\":64,\"items\":{\"$ref\":\"#/$defs/redactionRule\"}}}},\"redactionRule\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"rule_type\",\"name_pattern\"],\"properties\":{\"rule_type\":{\"type\":\"string\",\"enum\":[\"header\",\"cookie\",\"form_field\",\"query_param\"],\"description\":\"06.2.2 allowlist — a rule type outside it is rejected at write time (422 redaction_rule_type_unknown)\"},\"name_pattern\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":128}}}}}",
  "discover.v1": "{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"discover.v1.json\",\"title\":\"Adapter operation: discover v1\",\"description\":\"00 §10 protocol operation 'discover' (04.7.1-T1.2). Direction: adapter → server — the adapter reports the cases, variants and shards it can see for the locked suite revision, without any business side effect (source §4). The authoritative shard plan of a run is the manifest's (05.1.1); discover only proposes shard ids. The shared event envelope is referenced, never copied (00 §9.4). A failed phase reports `error` instead of the payload: at least one of `discovery` and `error` is required, never a silent success (contracts/adapter/README.md).\",\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"protocol\",\"operation\"],\"anyOf\":[{\"required\":[\"discovery\"]},{\"required\":[\"error\"]}],\"properties\":{\"protocol\":{\"$ref\":\"#/$defs/protocol\"},\"operation\":{\"const\":\"discover\"},\"run_id\":{\"type\":\"string\",\"format\":\"uuid\"},\"discovery\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"case_ids\"],\"properties\":{\"case_ids\":{\"type\":\"array\",\"maxItems\":10000,\"uniqueItems\":true,\"items\":{\"type\":\"string\",\"format\":\"uuid\"}},\"variant_hashes\":{\"type\":\"array\",\"maxItems\":256,\"uniqueItems\":true,\"items\":{\"type\":\"string\",\"pattern\":\"^[0-9a-f]{64}$\"}},\"shard_ids\":{\"type\":\"array\",\"maxItems\":256,\"uniqueItems\":true,\"items\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":64}}}},\"error\":{\"$ref\":\"#/$defs/operationError\"}},\"$defs\":{\"protocol\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"major\",\"minor\"],\"properties\":{\"major\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":2147483647},\"minor\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":2147483647}}},\"operationError\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"code\"],\"properties\":{\"code\":{\"type\":\"string\",\"pattern\":\"^[a-z][a-z0-9_]{0,63}$\",\"description\":\"lower_snake phase failure (e.g. setup_error); reported separately from events (source §4)\"},\"message\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":512}}}}}",
  "environment-requirements.v1": "{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"environment-requirements.v1.json\",\"title\":\"Suite environment requirements v1\",\"description\":\"What a suite revision needs from its environment, secret-free (03.2.1-T4.2, AC8): base URLs, dependency versions, warm-up, the data isolation mode (the single source for 05.7.3-T4) and the NAMES of the secrets the run needs. A secret value never appears here; the semantic secret-shape rules run in addition to this schema.\",\"type\":\"object\",\"additionalProperties\":false,\"properties\":{\"base_urls\":{\"type\":\"object\",\"maxProperties\":16,\"propertyNames\":{\"pattern\":\"^[a-z][a-z0-9_-]{0,31}$\"},\"additionalProperties\":{\"type\":\"string\",\"format\":\"uri\",\"maxLength\":512}},\"dependency_versions\":{\"type\":\"object\",\"maxProperties\":32,\"propertyNames\":{\"pattern\":\"^[A-Za-z0-9][A-Za-z0-9._@/-]{0,63}$\"},\"additionalProperties\":{\"type\":\"string\",\"maxLength\":64}},\"warm_up\":{\"type\":\"object\",\"additionalProperties\":false,\"properties\":{\"path\":{\"type\":\"string\",\"maxLength\":256},\"timeout_seconds\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":600}}},\"data_isolation\":{\"enum\":[\"isolated\",\"shared\"]},\"secrets\":{\"type\":\"array\",\"maxItems\":32,\"uniqueItems\":true,\"items\":{\"type\":\"string\",\"pattern\":\"^[A-Z][A-Z0-9_]{0,63}$\"}}}}",
  "environment-revision.v1": "{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"environment-revision.v1.json\",\"title\":\"Environment revision v1\",\"description\":\"The body of POST /v1/projects/{p}/environments/{e}/revisions (05.1.2-T1, 00 §9.3): the secret-free configuration of one target environment — base URLs and the dependency versions that affect results — plus secret references (never values). The server hashes base_urls, dependency_versions and the sorted secret_refs into revision_hash (sha256 over RFC 8785). Secret detection in values is the server's semantic check (reason secret_value_detected), not this schema's: a schema rule would not catch a token-shaped value either. The transport cap is 64 KiB.\",\"x-max-bytes\":65536,\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"base_urls\",\"dependency_versions\"],\"properties\":{\"name\":{\"type\":[\"string\",\"null\"],\"minLength\":1,\"maxLength\":128,\"description\":\"Display name; used when the call creates the environment, and renames it otherwise; null is the same as absent\"},\"revision_no\":{\"type\":[\"integer\",\"null\"],\"minimum\":1,\"maximum\":2147483647,\"description\":\"Optional optimistic check: the number the caller expects this revision to get; any other next number is 409 revision_conflict; null is the same as absent\"},\"base_urls\":{\"type\":\"object\",\"maxProperties\":32,\"propertyNames\":{\"pattern\":\"^[a-z][a-z0-9_]{0,63}$\"},\"additionalProperties\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":2048}},\"dependency_versions\":{\"type\":\"object\",\"maxProperties\":128,\"propertyNames\":{\"pattern\":\"^[A-Za-z0-9@][A-Za-z0-9@/._+-]{0,127}$\"},\"additionalProperties\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":128}},\"secret_refs\":{\"type\":\"array\",\"maxItems\":64,\"uniqueItems\":true,\"description\":\"References of the form secret:<name>; anything else is refused as a secret value (secret_value_detected) without being echoed\",\"items\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":256}}}}",
  "event-envelope.v1": "{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"event-envelope.v1.json\",\"title\":\"Event envelope v1\",\"description\":\"00 §9.4 event envelope. The body of POST /v1/runs/{r}/events is a batch { events: [...] }; the §9.4 example is a single event and also validates against this schema. Batch caps: maxItems 500 events and x-max-bytes 1048576 (1 MiB before decompression — enforced at the transport layer, declared here because JSON Schema cannot express byte size).\",\"x-max-bytes\":1048576,\"anyOf\":[{\"$ref\":\"#/$defs/event\"},{\"$ref\":\"#/$defs/batch\"}],\"$defs\":{\"batch\":{\"type\":\"object\",\"required\":[\"events\"],\"additionalProperties\":false,\"x-max-bytes\":1048576,\"properties\":{\"schema_version\":{\"const\":1},\"events\":{\"type\":\"array\",\"minItems\":1,\"maxItems\":500,\"items\":{\"$ref\":\"#/$defs/event\"}}}},\"event\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"schema_version\",\"event_id\",\"producer_id\",\"sequence\",\"execution_key\",\"attempt_no\",\"type\",\"occurred_at\"],\"properties\":{\"schema_version\":{\"const\":1},\"event_id\":{\"type\":\"string\",\"format\":\"uuid\"},\"producer_id\":{\"type\":\"string\",\"maxLength\":128},\"sequence\":{\"type\":\"integer\",\"minimum\":0},\"job_id\":{\"type\":[\"string\",\"null\"],\"format\":\"uuid\"},\"epoch\":{\"type\":\"integer\",\"minimum\":0},\"execution_key\":{\"type\":\"string\",\"pattern\":\"^[0-9a-f]{64}$\",\"description\":\"sha256(case_id ‖ variant_hash ‖ target_env) hex, computed by the server (00 §7)\"},\"attempt_no\":{\"type\":\"integer\",\"minimum\":1},\"type\":{\"type\":\"string\",\"maxLength\":64,\"pattern\":\"^[a-z][a-z0-9_]*(\\\\.[a-z][a-z0-9_]*)*$\",\"description\":\"Dotted lower_snake event type, e.g. test.started|test.step|test.finished|run.log|producer.heartbeat (00 §9.4)\"},\"status\":{\"type\":\"string\",\"maxLength\":64,\"description\":\"Raw producer status; required when type is test.finished (00 §9.4)\"},\"duration_ms\":{\"type\":\"integer\",\"minimum\":0},\"occurred_at\":{\"type\":\"string\",\"format\":\"date-time\",\"description\":\"RFC 3339 UTC; runner clock, informative only (00 §9.4)\"},\"artifact_ids\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"format\":\"uuid\"}},\"ext\":{\"type\":\"object\",\"required\":[\"schema\"],\"properties\":{\"schema\":{\"type\":\"string\",\"maxLength\":128}}}},\"allOf\":[{\"if\":{\"properties\":{\"type\":{\"const\":\"test.finished\"}},\"required\":[\"type\"]},\"then\":{\"required\":[\"status\"]}}]}}}",
  "execute.v1": "{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"execute.v1.json\",\"title\":\"Adapter operation: execute v1\",\"description\":\"00 §10 protocol operation 'execute' (04.7.1-T1.2). Direction: adapter → server — the per-attempt events a locked-manifest execution produced (source §4: 'events per attempt; deadline and cancel token'). Every entry is the shared 00 §9.4 event envelope, referenced by $id (urn:evidgate:contract:event-envelope.v1) and never copied: removing or renaming an envelope member changes this schema's verdicts without editing this file. At most 500 events, like the ingest batch (00 §9.3). A failed phase reports `error` instead of the payload: at least one of `events` and `error` is required (contracts/adapter/README.md).\",\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"protocol\",\"operation\"],\"anyOf\":[{\"required\":[\"events\"]},{\"required\":[\"error\"]}],\"properties\":{\"protocol\":{\"$ref\":\"#/$defs/protocol\"},\"operation\":{\"const\":\"execute\"},\"run_id\":{\"type\":\"string\",\"format\":\"uuid\"},\"events\":{\"type\":\"array\",\"minItems\":1,\"maxItems\":500,\"items\":{\"$ref\":\"urn:evidgate:contract:event-envelope.v1#/$defs/event\"}},\"error\":{\"$ref\":\"#/$defs/operationError\"}},\"$defs\":{\"protocol\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"major\",\"minor\"],\"properties\":{\"major\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":2147483647},\"minor\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":2147483647}}},\"operationError\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"code\"],\"properties\":{\"code\":{\"type\":\"string\",\"pattern\":\"^[a-z][a-z0-9_]{0,63}$\"},\"message\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":512}}}}}",
  "healing-switch-set.v1": "{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"healing-switch-set.v1.json\",\"title\":\"Healing switch set v1\",\"description\":\"The body of PUT /v1/healing/switch (08.6.3-T1, 00 §8.7, rulings T33/T72): the kill switch of one scope. The server refuses scope=system with 403 forbidden_scope (only the operator ingress writes the platform row), a project scope without a project_id, and a tenant scope that carries one, each as 422 with a field detail. `mode` is deliberately a free string here instead of an enum: the mode vocabulary is checked by the handler so that `unavailable` and every other value answer 422 invalid_switch_mode rather than a generic schema failure, and `enabled` answers 422 mode_not_available while the deployment runs with Healing:Apply off. The schema is closed: a member not listed here is refused with its JSON pointer in error.details[].path. The transport cap is 4 KiB.\",\"x-max-bytes\":4096,\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"scope\",\"mode\"],\"properties\":{\"scope\":{\"type\":\"string\",\"enum\":[\"system\",\"tenant\",\"project\"],\"description\":\"The scope the switch is set on; `system` is refused by this route (403 forbidden_scope)\"},\"project_id\":{\"type\":[\"string\",\"null\"],\"format\":\"uuid\",\"description\":\"The project of a `project` scope row; refused on a `tenant` row and required on a `project` row\"},\"mode\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":32,\"description\":\"One of enabled, shadow, disabled — anything else, `unavailable` included, is 422 invalid_switch_mode\"},\"reason\":{\"type\":[\"string\",\"null\"],\"minLength\":1,\"maxLength\":2000,\"description\":\"Why the switch was set, 1–2000 Unicode code points when present (a JSON-Schema string length counts characters, the same unit the column's length() check uses)\"}}}",
  "manifest.v1": "{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"manifest.v1.json\",\"title\":\"Manifest v1\",\"description\":\"The run manifest accepted by POST /v1/projects/{p}/manifests (05.1.1-T1.1/T1.2, 00 §9.3). It declares the suite revision, the planned executions (case revision × variant params × target env), the matrix those executions cover, the shard plan that partitions them and the per-environment needs. Bounds are encoded here: at most 10000 planned executions, 256 shards, 32 target environments, 32 variant params; the transport cap is 256 KiB [DECISION 05.1.1 §8]. Semantic checks — unknown case revision, secret literal in variant params, matrix coverage — are 05.1.1-T2's; this schema only fixes the shape.\",\"x-max-bytes\":262144,\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"schema_version\",\"suite_revision_id\",\"planned_executions\",\"matrix\",\"shard_plan\",\"env_needs\"],\"properties\":{\"schema_version\":{\"const\":1},\"suite_revision_id\":{\"type\":\"string\",\"format\":\"uuid\"},\"environment_revision_id\":{\"type\":[\"string\",\"null\"],\"format\":\"uuid\",\"description\":\"Optional in V1: environment_revision is created by 05.1.2-T1, which adds the composite FK (org_id, environment_revision_id)\"},\"planned_executions\":{\"type\":\"array\",\"maxItems\":10000,\"items\":{\"$ref\":\"#/$defs/plannedExecution\"}},\"matrix\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"case_revision_ids\",\"variants\",\"target_envs\"],\"properties\":{\"case_revision_ids\":{\"type\":\"array\",\"maxItems\":10000,\"items\":{\"type\":\"string\",\"format\":\"uuid\"},\"description\":\"Distinct ids; duplicates are matrix_not_covered (05.1.1-T2.4, a linear check). Deliberately no uniqueItems: the validators compare items pairwise, so 10000 ids would cost seconds per request.\"},\"variants\":{\"type\":\"array\",\"maxItems\":256,\"uniqueItems\":true,\"description\":\"The variant axis; planned_executions must equal case_revision_ids × variants × target_envs (05.1.1-T2.4)\",\"items\":{\"$ref\":\"#/$defs/variant\"}},\"target_envs\":{\"type\":\"array\",\"maxItems\":32,\"uniqueItems\":true,\"items\":{\"$ref\":\"#/$defs/targetEnv\"}}}},\"shard_plan\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"shards\"],\"properties\":{\"shards\":{\"type\":\"array\",\"minItems\":1,\"maxItems\":256,\"description\":\"One entry per producer slot (05.2.1 registers one per shard); the index ranges partition planned_executions exactly (05.1.1-T2.4)\",\"items\":{\"$ref\":\"#/$defs/shard\"}}}},\"env_needs\":{\"$ref\":\"#/$defs/envNeeds\"}},\"$defs\":{\"plannedExecution\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"case_revision_id\",\"variant\",\"target_env\"],\"properties\":{\"case_revision_id\":{\"type\":\"string\",\"format\":\"uuid\"},\"variant\":{\"$ref\":\"#/$defs/variant\"},\"target_env\":{\"$ref\":\"#/$defs/targetEnv\"},\"required\":{\"type\":\"boolean\",\"default\":true,\"description\":\"Absent means required (05.2.1 planned_execution.required defaults true); an optional tuple is reported but cannot by itself make the run complete\"}}},\"variant\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"params\"],\"properties\":{\"params\":{\"$ref\":\"#/$defs/params\"}}},\"params\":{\"type\":\"object\",\"maxProperties\":32,\"description\":\"Normalised secret-free variant parameters (03.2.1): the server hashes them into variant_hash, and execution_key = sha256(case_id ‖ variant_hash ‖ target_env) (00 §7). A literal where a secret is meant is rejected by 05.1.1-T2.3, not by this schema.\",\"propertyNames\":{\"pattern\":\"^[a-z][a-z0-9_]{0,63}$\"},\"additionalProperties\":{\"type\":\"string\",\"maxLength\":256}},\"targetEnv\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":64,\"pattern\":\"^[a-z0-9][a-z0-9_-]{0,63}$\"},\"shard\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"shard_id\",\"from_index\",\"to_index\"],\"properties\":{\"shard_id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":64,\"pattern\":\"^[A-Za-z0-9][A-Za-z0-9_.-]{0,63}$\"},\"from_index\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":9999,\"description\":\"Inclusive start index into planned_executions\"},\"to_index\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":10000,\"description\":\"Exclusive end index into planned_executions; a shard owns [from_index, to_index)\"},\"producer_hint\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":64,\"description\":\"Versioned producer metadata for the pool; never authoritative (00 §5.4.5)\"}}},\"envNeeds\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"target_envs\"],\"properties\":{\"target_envs\":{\"type\":\"array\",\"maxItems\":32,\"description\":\"One entry per target env of the matrix; secrets are references only (00 §5.7 S3)\",\"items\":{\"$ref\":\"#/$defs/envNeed\"}}}},\"envNeed\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"target_env\"],\"properties\":{\"target_env\":{\"$ref\":\"#/$defs/targetEnv\"},\"secret_refs\":{\"type\":\"array\",\"maxItems\":64,\"uniqueItems\":true,\"items\":{\"type\":\"string\",\"pattern\":\"^secret:[A-Za-z0-9_.-]{1,64}$\"}}}}}}",
  "policy-revision.v1": "{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"policy-revision.v1.json\",\"title\":\"Policy revision v1\",\"description\":\"The body of POST /v1/projects/{p}/policies (07.1.1-T3, 00 §8.6 + D-A10): the decision-rule configuration of one project — the cases and suites a run must cover, the critical cases, the skips the policy allows, the flaky budget, the required artifacts, the collection deadline and late window, the freshness bound, the quarantine list and the branch-gating references. The server canonicalises the body (RFC 8785) and hashes it into `sha256:<hex>`; content already stored for the project answers 200 with that revision, new content 201 with the next revision_no. The schema is closed: any member not listed here is refused as 422 policy_unknown_field with the member's JSON pointer in error.details[].path. The transport cap is 64 KiB.\",\"x-max-bytes\":65536,\"type\":\"object\",\"additionalProperties\":false,\"properties\":{\"required_suites\":{\"type\":\"array\",\"maxItems\":1000,\"uniqueItems\":true,\"description\":\"Suites whose evidence the run must carry\",\"items\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":200}},\"required_cases\":{\"type\":\"array\",\"maxItems\":1000,\"uniqueItems\":true,\"description\":\"Cases whose evidence the run must carry\",\"items\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":200}},\"critical_cases\":{\"type\":\"array\",\"maxItems\":1000,\"uniqueItems\":true,\"description\":\"Cases that can never be quarantined and can never be skipped (00 §8.6, DECISIONS O9)\",\"items\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":200}},\"allowed_skips\":{\"type\":\"array\",\"maxItems\":1000,\"uniqueItems\":true,\"description\":\"Cases the policy allows to be skipped without making the run INCONCLUSIVE\",\"items\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":200}},\"flaky_budget\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":10000,\"description\":\"How many non-critical fail → pass flips the policy tolerates before the decision becomes INCONCLUSIVE with reason flaky_budget_exceeded (00 §8.6, TL T27)\"},\"required_artifacts\":{\"type\":\"array\",\"maxItems\":100,\"uniqueItems\":true,\"description\":\"Artifact kinds the run must produce (00 §7 kind names)\",\"items\":{\"type\":\"string\",\"pattern\":\"^[a-z][a-z0-9_]{0,63}$\"}},\"collection_timeout_minutes\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":10080,\"description\":\"Deadline for a run's collection phase, in minutes\"},\"late_window_minutes\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":10080,\"description\":\"How long after the deadline late evidence is still accepted (00 §8.1, TL T81)\"},\"freshness_minutes\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":525600,\"description\":\"Maximum age of the evidence a run may pin, in minutes\"},\"quarantine_ids\":{\"type\":\"array\",\"maxItems\":1000,\"uniqueItems\":true,\"description\":\"Quarantine entries this policy revision honours; the list is stored as given and honoured at evaluation time. The refusal of a critical case belongs to POST /v1/quarantine (07.3.1).\",\"items\":{\"type\":\"string\",\"format\":\"uuid\"}},\"gating_refs\":{\"type\":\"object\",\"additionalProperties\":false,\"description\":\"Branch policy for gated runs (DECISIONS D-A10)\",\"properties\":{\"default_branch\":{\"type\":\"boolean\",\"description\":\"Whether the repository's default branch is gated\"},\"release_branch_glob\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":200,\"description\":\"Glob of the release branches that are gated\"}}}}}",
  "prepare.v1": "{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"prepare.v1.json\",\"title\":\"Adapter operation: prepare v1\",\"description\":\"00 §10 protocol operation 'prepare' (04.7.1-T1.2). Direction: adapter → server — the adapter reports the sandbox/workspace it provisioned, the engine it will run and the secret references it resolved (source §4: 'sandbox, test data, engine; reports setup errors separately'). Secrets travel as references only, never as values (00 §5.7 S3). A failed phase reports `error` instead of the payload: at least one of `workspace` and `error` is required (contracts/adapter/README.md).\",\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"protocol\",\"operation\"],\"anyOf\":[{\"required\":[\"workspace\"]},{\"required\":[\"error\"]}],\"properties\":{\"protocol\":{\"$ref\":\"#/$defs/protocol\"},\"operation\":{\"const\":\"prepare\"},\"run_id\":{\"type\":\"string\",\"format\":\"uuid\"},\"workspace\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"workspace_id\"],\"properties\":{\"workspace_id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":128},\"engine\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"family\",\"version\"],\"properties\":{\"family\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":64},\"version\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":128}}},\"secret_refs\":{\"type\":\"array\",\"maxItems\":64,\"uniqueItems\":true,\"items\":{\"type\":\"string\",\"pattern\":\"^secret:[A-Za-z0-9_.-]{1,64}$\"}}}},\"error\":{\"$ref\":\"#/$defs/operationError\"}},\"$defs\":{\"protocol\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"major\",\"minor\"],\"properties\":{\"major\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":2147483647},\"minor\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":2147483647}}},\"operationError\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"code\"],\"properties\":{\"code\":{\"type\":\"string\",\"pattern\":\"^[a-z][a-z0-9_]{0,63}$\"},\"message\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":512}}}}}",
  "retry-policy.v1": "{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"retry-policy.v1.json\",\"title\":\"Suite retry policy v1\",\"description\":\"How often a failed attempt is retried and for which statuses (03.2.1-T4.1). A retry is a new attempt; it never replaces the first result (00 §8).\",\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"max_retries\"],\"properties\":{\"max_retries\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":5},\"only_on_status\":{\"type\":\"array\",\"maxItems\":3,\"uniqueItems\":true,\"items\":{\"enum\":[\"failed\",\"error\",\"timed_out\"]}}}}",
  "shard-strategy.v1": "{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"shard-strategy.v1.json\",\"title\":\"Suite shard strategy v1\",\"description\":\"How a suite revision is split across CI shards (03.2.1-T4.1). `none` runs everything in one shard; `count` splits into `count` shards, optionally balanced by recorded duration or by case count.\",\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"kind\"],\"properties\":{\"kind\":{\"enum\":[\"none\",\"count\"]},\"count\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":256},\"balance_by\":{\"enum\":[\"duration\",\"count\"]}},\"allOf\":[{\"if\":{\"properties\":{\"kind\":{\"const\":\"count\"}}},\"then\":{\"required\":[\"count\"]},\"else\":{\"not\":{\"anyOf\":[{\"required\":[\"count\"]},{\"required\":[\"balance_by\"]}]}}}]}",
  "sidecar.v1": "{\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"$id\":\"sidecar.v1.json\",\"title\":\"Case sidecar manifest v1\",\"description\":\"The evidgate.cases.yaml file that sits next to the test files it describes (03.1.1, TL T55): it maps each test file of its own directory to the durable evidgate.id of the case it holds. The YAML is converted to JSON and validated against this schema; semantic checks (the file exists in the tree, no duplicate file entry, no second source) are the reader's. The file is parsed as plain data: anchors, tags and merge keys are refused before this point.\",\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"version\",\"cases\"],\"properties\":{\"version\":{\"const\":1},\"cases\":{\"type\":\"array\",\"maxItems\":5000,\"items\":{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"file\",\"evidgate.id\"],\"properties\":{\"file\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":1024,\"description\":\"Path relative to the manifest's own directory, forward slashes, no leading slash, no '..' segment.\"},\"evidgate.id\":{\"type\":\"string\",\"format\":\"uuid\"},\"name\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":512}}}}}}",
};
